import{_ as s,l,o as r,c as o,v as c,p as d,x as i,d as t,i as p,S as h,b as e}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"交叉货币互换定价","description":"","frontmatter":{"title":"交叉货币互换定价","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/xccy-swap-pricing.md","filePath":"quant/xccy-swap-pricing.md","lastUpdated":1789023840000}'),E={name:"quant/xccy-swap-pricing.md"};function u(A,a,x,F,m,B){const n=l("Mermaid");return r(),o("div",null,[a[1]||(a[1]=c('<h1 id="交叉货币互换定价" tabindex="-1">交叉货币互换定价 <a class="header-anchor" href="#交叉货币互换定价" aria-label="Permalink to &quot;交叉货币互换定价&quot;">​</a></h1><div class="epigraph"><p>交叉货币基差把「用外国曲线贴现外国腿」这条教科书等式打破；本金交换与基差报价是同一件事的两面。</p><footer>—— 多曲线与 xccy 基差见 Fujii, Shimada and Takahashi 以及市场上 USD/JPY、EUR/USD 基差报价惯例</footer></div><p><a href="/quant/fx-barrier-touch">上一课</a>还在 FX 期权路径。交叉货币互换（xccy swap）的缺口是<strong>线性产品里的基差</strong>：交换本金、交换浮息，报价却是一腿上的基差利差，而不是 GK 的 \\(\\sigma\\)。主干 <a href="/quant/xccy-basis">交叉货币基差</a> 已写经济含义。本课写定价引擎如何把基差曲线与两条单货币曲线、FX 远期一起用，接到后课商品之前把 FX 线性产品收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书：把外币腿用外币 OIS 贴现，本币腿用本币 OIS，用 FX 远期把未来现金流换成同一货币，价值应为零。危机后同一信用等级的美元与欧元折现仍差一截，市场用 USD/EUR 基差互换把差报价出来。问题是引擎：三条曲线（USD 贴现、EUR 贴现、EUR 预测或反过来）加 FX 远期，必须联合校准到存款、单货币互换、FX swap 与 xccy 基差，否则期权里用的 \\(F\\) 与互换里用的 \\(F\\) 不一致。</p><p>本金交换在期初与期末。基差主要补偿的是「借一种货币、贷另一种」的资金差，不是预期即期的方向。把 xccy 当 FX 方向性产品，会与 Delta 对冲的远期簿重复计算。</p><h3 id="多曲线是约束-不是装饰" tabindex="-1">多曲线是约束，不是装饰 <a class="header-anchor" href="#多曲线是约束-不是装饰" aria-label="Permalink to &quot;多曲线是约束，不是装饰&quot;">​</a></h3><p><a href="/quant/multi-curve-ois">OIS 多曲线</a> 在单货币里已经把预测与贴现分开。xccy 再把贴现拆成按货币、按抵押货币。CSA 若以 USD 现金为抵押，欧元腿的贴现也不再是欧元 OIS。定价必须以净额集的抵押货币为准，这与 <a href="/quant/xva-bridge">XVA 桥</a> 同一逻辑。</p><p><span class="marginnote">基差可为负（日元长期如此）。模型允许负基差，并不等于允许负的单货币利率——后课移位是另一件事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校准顺序：先各货币 OIS 与 IBOR/RFR 预测，再 FX swap 短端，再 xccy 基差长端，检查再定价误差。估值：投影每条腿的浮息，用对应贴现曲线贴现，期初期末本金用 FX 与贴现换成报告货币。对冲：各货币 DV01 + FX Delta + 基差桶。不要用单一「外汇 Rho」代替基差桶。</p><p>MTM 与 reset：部分 xccy 有定期本金重设，降低 CVA 暴露，改变基差敏感度。条款要当状态机，不能当普通固定-浮动。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无基差时，FX 远期与利率平价一致，互换公平价差为零。有基差时，市场在说：用欧元抵押的欧元现金与用美元抵押的美元现金，不能通过 FX 无摩擦转换。定价核把这句写成贴现曲线的差。期权的 quanto 调整用的相关，与这条资金基差不是同一个 \\(\\rho\\)；不要把 xccy 基差当股权-FX 相关的代理。</p>',14)),(r(),d(h,null,{default:i(()=>[p(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20OIS%5B%22%E5%90%84%E8%B4%A7%E5%B8%81%20OIS%20%E4%B8%8E%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20Joint%5B%22%E8%81%94%E5%90%88%E6%A0%A1%E5%87%86%22%5D%0A%20%20FXsw%5B%22FX%20swap%22%5D%20--%3E%20Joint%0A%20%20Basis%5B%22xccy%20%E5%9F%BA%E5%B7%AE%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20Joint%0A%20%20Joint%20--%3E%20PV%5B%22%E5%8F%8C%E8%85%BF%E5%8A%A0%E6%9C%AC%E9%87%91%E4%BA%A4%E6%8D%A2%E7%9A%84%20PV%22%5D%0A%20%20PV%20--%3E%20Hdg%5B%22DV01%20%E5%8A%A0%20FX%20Delta%20%E5%8A%A0%E5%9F%BA%E5%B7%AE%E6%A1%B6%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"边界",tabindex:"-1"},[t("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[3]||(a[3]=e("p",null,"LIBOR 停用后的 RFR xccy、历史基差与新惯例不可混。流动性差的货币对只有短端 FX swap，长端基差外推是模型风险。XVA：xccy 暴露对 FX 高度敏感，CVA 与 IM 必须用同一 FX 动态。",-1)),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"xccy 定价是多曲线加 FX 远期加基差曲线的联合校准，不是 GK 的附属品。"),e("li",null,"本金交换与抵押货币决定贴现；对冲要单独的基差桶。"),e("li",null,"基差是资金与抵押，不是方向性 FX 观点。"),e("li",null,"出处：Fujii, Shimada and Takahashi 关于多货币曲线的工作；市场基差报价惯例。")],-1))])}const X=s(E,[["render",u]]);export{S as __pageData,X as default};
